function SearchOverlay({ products, close, onWishlist, wished }: { products: Product[]; close: () => void; onWishlist: (id: string) => void; wished: string[] }) {
  const [query, setQuery] = useState('');
  const results = products.filter(p => p.name.toLowerCase().includes(query.toLowerCase()) || p.category.toLowerCase().includes(query.toLowerCase()));
  return <div className="fixed inset-0 z-50 bg-[#eee9dd] p-5 md:p-10"><div className="mx-auto max-w-[1100px]"><div className="flex items-center justify-between"><Logo/><button onClick={close} aria-label="Close search" data-testid="button-close-search"><X size={24} strokeWidth={1.3}/></button></div><div className="mt-20 flex items-center gap-4 border-b-2 border-[#1f293b] pb-3"><Search size={25} strokeWidth={1.3}/><input autoFocus value={query} onChange={e => setQuery(e.target.value)} data-testid="input-search" className="w-full bg-transparent font-serif text-5xl outline-none placeholder:text-[#9d9b93]" placeholder="Search the collection"/></div><div className="mt-10 grid grid-cols-2 gap-4 md:grid-cols-4">{results.map(p => <ProductCard key={p.id} product={p} onWishlist={onWishlist} wished={wished.includes(p.id)}/>)}</div>{query && results.length === 0 && <p className="mt-12 font-serif text-3xl">Nothing by that name. Try another edit.</p>}</div></div>;
}

function CartDrawer({ cart, close, update, checkout }: { cart: CartLine[]; close: () => void; update: (id: string, size: string, delta: number) => void; checkout: () => void }) {
  const total = cart.reduce((sum, l) => sum + l.product.price * l.quantity, 0);
  return <div className="fixed inset-0 z-50"><button onClick={close} aria-label="Close bag overlay" data-testid="button-close-cart-overlay" className="absolute inset-0 bg-[#1f293b]/40"/><aside className="absolute right-0 top-0 flex h-full w-full max-w-md flex-col bg-[#eee9dd] shadow-2xl"><div className="flex items-center justify-between border-b hairline p-5"><div><p className="eyebrow text-[#ac2536]">Your selection</p><h2 className="mt-1 font-serif text-3xl">The bag</h2></div><button onClick={close} aria-label="Close bag" data-testid="button-close-cart"><X size={22} strokeWidth={1.3}/></button></div><div className="flex-1 overflow-auto p-5">{cart.length === 0 ? <div className="flex h-full flex-col items-center justify-center text-center"><ShoppingBag size={32} strokeWidth={1} className="text-[#ac2536]"/><p className="mt-5 font-serif text-3xl">Your bag is quiet.</p><Link href="/shop" onClick={close} data-testid="link-empty-shop" className="editorial-link mt-5 font-mono text-[10px] uppercase tracking-widest">Explore the collection</Link></div> : <div className="grid gap-6">{cart.map(line => <div key={`${line.product.id}-${line.size}`} className="flex gap-4" data-testid={`line-cart-${line.product.id}`}><img src={line.product.image} alt={line.product.name} className="h-28 w-24 object-cover object-[center_20%] mix-blend-multiply"/><div className="flex flex-1 flex-col justify-between"><div className="flex justify-between gap-3"><div><p className="font-serif text-xl">{line.product.name}</p><p className="mt-1 font-mono text-[9px] uppercase tracking-widest text-[#6f716e]">Size {line.size}</p></div><span className="font-mono text-xs">{money(line.product.price * line.quantity)}</span></div><div className="flex items-center gap-3"><button onClick={() => update(line.product.id,line.size,-1)} aria-label="Decrease quantity" data-testid={`button-decrease-${line.product.id}`} className="border hairline p-1"><Minus size={12}/></button><span className="font-mono text-xs">{line.quantity}</span><button onClick={() => update(line.product.id,line.size,1)} aria-label="Increase quantity" data-testid={`button-increase-${line.product.id}`} className="border hairline p-1"><Plus size={12}/></button></div></div></div>)}</div>}</div>{cart.length > 0 && <div className="border-t hairline p-5"><div className="flex justify-between font-mono text-xs uppercase tracking-widest"><span>Total</span><span>{money(total)}</span></div><button onClick={checkout} data-testid="button-checkout" className="mt-5 flex w-full items-center justify-center gap-2 bg-[#ac2536] py-4 font-mono text-[10px] uppercase tracking-[.18em] text-[#eee9dd] transition-transform hover:-translate-y-1">Continue to checkout <ArrowUpRight size={15}/></button><p className="mt-3 text-center font-mono text-[9px] uppercase tracking-widest text-[#6f716e]">Complimentary delivery over $400</p></div>}</aside></div>;
}

function Shop({ products, onWishlist, wished, cartCount, onCart, onSearch }: { products: Product[]; onWishlist: (id: string) => void; wished: string[]; cartCount: number; onCart: () => void; onSearch: () => void }) {
  const [location] = useLocation(); const params = new URLSearchParams(location.split('?')[1] || '');
  const [category, setCategory] = useState(params.get('category') || 'All pieces'); const [query, setQuery] = useState(''); const [ascending, setAscending] = useState(true);
  const categories = ['All pieces', 'New', 'Outerwear', 'Trousers', 'Shirting', 'Knitwear', 'Separates'];
  const shown = products.filter(p => (category === 'All pieces' || category === 'New' ? category === 'New' ? p.badge === 'New' : p.category === category : p.category === category) && `${p.name} ${p.category}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => ascending ? a.price - b.price : b.price - a.price);
  return <><Header cartCount={cartCount} onCart={onCart} onSearch={onSearch}/><main className="mx-auto max-w-[1440px] px-5 py-12 md:px-10 md:py-20"><div className="flex flex-col justify-between gap-8 border-b hairline pb-10 md:flex-row md:items-end"><div><p className="eyebrow text-[#ac2536]">The collection / 2026</p><h1 className="mt-4 font-serif text-6xl leading-[.85] md:text-8xl">Considered<br/><i>pieces.</i></h1></div><p className="max-w-xs text-sm leading-6 text-[#6f716e]">A small wardrobe of lasting forms, made for the way you actually live.</p></div><div className="sticky top-[74px] z-20 -mx-5 mt-6 flex gap-3 overflow-auto border-b hairline bg-[#eee9dd]/95 px-5 py-4 backdrop-blur-md scrollbar-none md:mx-0 md:px-0"><div className="flex shrink-0 gap-2">{categories.map(c => <button key={c} onClick={() => setCategory(c)} data-testid={`filter-${c.toLowerCase().replaceAll(' ','-')}`} className={`rounded-full border px-4 py-2 font-mono text-[9px] uppercase tracking-widest transition-colors ${category === c ? 'border-[#1f293b] bg-[#1f293b] text-[#eee9dd]' : 'hairline hover:border-[#ac2536] hover:text-[#ac2536]'}`}>{c}</button>)}</div><label className="ml-auto hidden items-center gap-2 border-b hairline px-2 md:flex"><Search size={15}/><input value={query} onChange={e => setQuery(e.target.value)} data-testid="input-shop-search" placeholder="Search" className="w-28 bg-transparent py-1 text-xs outline-none"/></label></div><div className="mb-8 mt-10 flex items-center justify-between"><p className="font-mono text-[10px] uppercase tracking-widest text-[#6f716e]">{shown.length} pieces</p><label className="flex items-center gap-2 border-b hairline px-2 md:hidden"><Search size={14}/><input value={query} onChange={e => setQuery(e.target.value)} data-testid="input-shop-search-mobile" placeholder="Search" className="w-24 bg-transparent py-1 text-xs outline-none"/></label><button onClick={() => setAscending(!ascending)} data-testid="button-sort" className="flex items-center gap-2 font-mono text-[10px] uppercase tracking-widest">Price {ascending ? 'low to high' : 'high to low'} <ChevronDown size={14}/></button></div>{shown.length ? <div className="grid grid-cols-2 gap-x-3 gap-y-12 md:grid-cols-3 md:gap-x-5 md:gap-y-16">{shown.map(p => <ProductCard key={p.id} product={p} onWishlist={onWishlist} wished={wished.includes(p.id)}/>)}</div> : <div className="border-y hairline py-24 text-center"><p className="font-serif text-4xl">No pieces found.</p><button onClick={() => {setCategory('All pieces'); setQuery('')}} data-testid="button-reset-filters" className="editorial-link mt-5 font-mono text-[10px] uppercase tracking-widest">Reset filters</button></div>}</main><Footer/></>;
}

function ProductDetail({ products, add, onWishlist, wished, cartCount, onCart, onSearch }: { products: Product[]; add: (p: Product, s: string) => void; onWishlist: (id: string) => void; wished: string[]; cartCount: number; onCart: () => void; onSearch: () => void }) {
  const { id } = useParams(); const product = products.find(p => p.id === id) || products[0]; const [size, setSize] = useState(product.sizes[1] || product.sizes[0]); const [saved, setSaved] = useState(false); const [guide, setGuide] = useState(false);
  useEffect(() => setSize(product.sizes[1] || product.sizes[0]), [product.id, product.sizes]);
  return <><Header cartCount={cartCount} onCart={onCart} onSearch={onSearch}/><main><div className="mx-auto grid max-w-[1440px] gap-0 md:grid-cols-[1.15fr_.85fr]"><div className="grid grid-cols-2 gap-1 bg-[#d7d4cb]"><div className="col-span-2 aspect-[1.1] overflow-hidden"><img src={product.image} alt={product.name} className="h-full w-full object-cover object-[center_18%] mix-blend-multiply"/></div><div className="aspect-square overflow-hidden bg-[#c5c6bc]"><img src={product.image} alt={`${product.name} detail`} className="h-full w-full object-cover object-[30%_20%] mix-blend-multiply"/></div><div className="aspect-square overflow-hidden bg-[#d6c0b4]"><img src={product.image} alt={`${product.name} texture`} className="h-full w-full object-cover object-[75%_25%] mix-blend-multiply"/></div></div><div className="flex flex-col justify-center px-5 py-12 md:px-16 lg:px-24"><Link href="/shop" data-testid="link-back-shop" className="eyebrow text-[#ac2536]">← The collection</Link><div className="mt-16 flex items-start justify-between gap-4"><div><p className="eyebrow text-[#6f716e]">{product.category} / {product.badge}</p><h1 className="mt-4 font-serif text-6xl leading-[.82] md:text-8xl">{product.name}</h1></div><button onClick={() => { onWishlist(product.id); setSaved(!saved); }} aria-label="Toggle wishlist" data-testid="button-product-wishlist" className={`mt-2 rounded-full border p-3 ${wished.includes(product.id) ? 'border-[#ac2536] text-[#ac2536]' : 'hairline'}`}><Heart size={19} fill={wished.includes(product.id) ? 'currentColor' : 'none'} strokeWidth={1.3}/></button></div><p className="mt-8 font-mono text-lg">{money(product.price)}</p><p className="mt-7 max-w-md text-sm leading-7 text-[#565d62]">{product.description}</p><div className="mt-12 border-t hairline pt-5"><div className="flex items-center justify-between"><p className="eyebrow">Select size</p><button onClick={() => setGuide(!guide)} data-testid="button-size-guide" className="font-mono text-[9px] uppercase tracking-widest underline underline-offset-4">Size guide</button></div>{guide && <div data-testid="size-guide" className="mt-4 bg-[#d8d5cc] p-4 text-xs leading-5 text-[#565d62]">Our pieces are designed with ease. If between sizes, take your usual size for a relaxed fit, or one down for a closer line.</div>}<div className="mt-4 flex gap-2">{product.sizes.map(s => <button key={s} onClick={() => setSize(s)} data-testid={`button-size-${s}`} className={`flex h-11 w-12 items-center justify-center border font-mono text-xs transition-colors ${size === s ? 'border-[#1f293b] bg-[#1f293b] text-[#eee9dd]' : 'hairline hover:border-[#ac2536]'}`}>{s}</button>)}</div></div><button onClick={() => add(product, size)} data-testid="button-add-to-bag" className="mt-7 flex w-full items-center justify-between bg-[#ac2536] px-5 py-4 font-mono text-[10px] uppercase tracking-[.18em] text-[#eee9dd] transition-transform hover:-translate-y-1"><span>Add to bag</span><span>{product.stock} available <ArrowUpRight className="ml-2 inline" size={15}/></span></button><div className="mt-8 grid gap-3 border-t hairline pt-6 font-mono text-[9px] uppercase tracking-widest text-[#6f716e]"><span>Made in small quantities</span><span>Complimentary delivery over $400</span><span>30 day returns, always</span></div></div></div><section className="bg-[#1f293b] px-5 py-20 text-[#eee9dd] md:px-10 md:py-28"><div className="mx-auto grid max-w-[1440px] gap-10 md:grid-cols-2"><p className="eyebrow text-[#d66a60]">A closer look</p><p className="max-w-xl font-serif text-4xl leading-tight md:text-6xl">The best clothes become invisible. You just become more yourself.</p></div></section></main><Footer/></>;
}

function AdminLogin({ onLogin }: { onLogin: () => void }) {
  const [, navigate] = useLocation(); const [password, setPassword] = useState(''); const [error, setError] = useState('');
  useEffect(() => { if (localStorage.getItem('lume-admin') === 'true') navigate('/admin'); }, [navigate]);
  const submit = (e: React.FormEvent) => { e.preventDefault(); if (password === 'atelier2026') { localStorage.setItem('lume-admin','true'); onLogin(); navigate('/admin'); } else setError('That password does not match the atelier key.'); };
  return <div className="grain flex min-h-[100dvh] items-center justify-center bg-[#1f293b] px-5 text-[#eee9dd]"><div className="w-full max-w-md"><div className="flex justify-center"><Logo inverse/></div><div className="mt-16 border border-[#c8c1b3]/25 p-7 md:p-10"><p className="eyebrow text-[#d66a60]">Private portal</p><h1 className="mt-5 font-serif text-5xl leading-none">Welcome back<br/><i>to Auren.</i></h1><p className="mt-6 text-sm leading-6 text-[#c8c1b3]">Manage the collection and keep the quiet work moving.</p><form onSubmit={submit} className="mt-10"><input type="text" name="username" autoComplete="username" value="admin" readOnly className="sr-only" aria-hidden="true"/><label className="eyebrow text-[#c8c1b3]">Password</label><div className="mt-3 flex items-center border-b border-[#c8c1b3]/50"><LockKeyhole size={15} className="mr-3 text-[#d66a60]"/><input type="password" value={password} onChange={e => {setPassword(e.target.value);setError('')}} data-testid="input-admin-password" className="w-full bg-transparent py-3 text-lg outline-none" autoComplete="current-password"/></div>{error && <p data-testid="status-login-error" className="mt-3 text-xs text-[#f1b2a5]">{error}</p>}<button type="submit" data-testid="button-admin-login" className="mt-8 flex w-full justify-center bg-[#ac2536] py-4 font-mono text-[10px] uppercase tracking-[.18em]">Enter portal <ArrowUpRight size={15} className="ml-2"/></button></form><p className="mt-8 border-t border-[#c8c1b3]/20 pt-5 font-mono text-[9px] uppercase tracking-widest text-[#c8c1b3]/70">Demo starter password: atelier2026</p></div><Link href="/" data-testid="link-login-home" className="mx-auto mt-8 block w-fit font-mono text-[10px] uppercase tracking-widest text-[#c8c1b3]">Return to storefront</Link></div></div>;
}

function Admin({ products, setProducts }: { products: Product[]; setProducts: React.Dispatch<React.SetStateAction<Product[]>> }) {
  const [, navigate] = useLocation();
  const [tab, setTab] = useState<AdminTab>('overview');
  const [editing, setEditing] = useState<Product | null>(null);
  const [notice, setNotice] = useState('');
  const [profile, setProfile] = useState<AdminProfile>(() => getStored('auren-admin-profile', defaultProfile));
  const [profileForm, setProfileForm] = useState<AdminProfile>(profile);
  const [bank, setBank] = useState<BankSummary>(() => getStored('auren-bank-summary', defaultBank));
  const [bankForm, setBankForm] = useState({ accountName: bank.accountName, bankName: bank.bankName, accountNumber: '', sortCode: '' });

  useEffect(() => { if (localStorage.getItem('lume-admin') !== 'true') navigate('/admin/login'); }, [navigate]);
  useEffect(() => { localStorage.setItem('auren-admin-profile', JSON.stringify(profile)); }, [profile]);
  useEffect(() => { localStorage.setItem('auren-bank-summary', JSON.stringify(bank)); }, [bank]);

  const flash = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(''), 2800); };
  const logout = () => { localStorage.removeItem('lume-admin'); navigate('/admin/login'); };
  const remove = (id: string) => { if (window.confirm('Remove this piece from the collection?')) { setProducts(ps => ps.filter(p => p.id !== id)); flash('Piece removed from the collection.'); } };
  const addProduct = () => setEditing({ id: `piece-${Date.now()}`, name: '', category: 'Outerwear', price: 0, image: '/lume-editorial.jpg', description: '', sizes: ['S', 'M', 'L'], badge: 'New', stock: 0 });
  const saveProfile = (event: React.FormEvent) => { event.preventDefault(); setProfile(profileForm); flash('Your contact details have been updated.'); };
  const saveBank = (event: React.FormEvent) => {
    event.preventDefault();
    const accountDigits = bankForm.accountNumber.replace(/\D/g, '');
    const sortDigits = bankForm.sortCode.replace(/\D/g, '');
    if (!bankForm.accountName.trim() || !bankForm.bankName.trim() || (accountDigits.length < 4 && !bank.accountNumberLast4)) { flash('Add your account name, bank and account number to continue.'); return; }
    setBank({ accountName: bankForm.accountName.trim(), bankName: bankForm.bankName.trim(), accountNumberLast4: accountDigits.slice(-4) || bank.accountNumberLast4, sortCodeLast4: sortDigits.slice(-4) || bank.sortCodeLast4, updatedAt: 'Just now' });
    setBankForm(form => ({ ...form, accountNumber: '', sortCode: '' }));
    flash('Payout details saved securely as a masked summary.');
  };
  const tabs: { id: AdminTab; label: string; icon: typeof LayoutDashboard }[] = [
    { id: 'overview', label: 'Overview', icon: LayoutDashboard },
    { id: 'products', label: 'Products', icon: Package },
    { id: 'orders', label: 'Orders & tracking', icon: Truck },
    { id: 'transactions', label: 'Transactions', icon: CreditCard },
    { id: 'settings', label: 'Your details', icon: Settings2 },
  ];
  const pageTitle = { overview: 'The control room.', products: 'Your collection.', orders: 'Goods in motion.', transactions: 'Money, accounted for.', settings: 'Your details.' }[tab];
  const pageIntro = { overview: 'Good morning, Auren.', products: 'Upload and shape each piece yourself.', orders: 'Follow every order from purchase to doorstep.', transactions: 'A clear view of your recent payouts.', settings: 'Keep your contact and payout details current.' }[tab];

  return <div className="min-h-[100dvh] bg-[#e7e2d6]">
    <header className="border-b hairline bg-[#1f293b] text-[#eee9dd]"><div className="mx-auto flex h-20 max-w-[1500px] items-center justify-between px-5 md:px-10"><Logo inverse/><div className="flex items-center gap-5"><span className="hidden font-mono text-[9px] uppercase tracking-widest text-[#c8c1b3] md:block">Auren / Control room</span><button onClick={logout} data-testid="button-admin-logout" className="flex items-center gap-2 font-mono text-[10px] uppercase tracking-widest text-[#d66a60]"><LogOut size={15}/> Exit</button></div></div></header>
    <div className="mx-auto grid max-w-[1500px] gap-10 px-5 py-8 md:px-10 md:py-12 lg:grid-cols-[220px_1fr]">
      <aside className="lg:pt-2"><p className="eyebrow text-[#6f716e]">Manage Auren</p><nav className="mt-4 flex gap-2 overflow-auto lg:grid lg:gap-1">{tabs.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setTab(id)} data-testid={`admin-tab-${id}`} className={`flex shrink-0 items-center gap-3 px-3 py-3 text-left font-mono text-[10px] uppercase tracking-widest transition-colors ${tab === id ? 'bg-[#1f293b] text-[#eee9dd]' : 'text-[#6f716e] hover:bg-[#d8d5cc] hover:text-[#1f293b]'}`}><Icon size={15} strokeWidth={1.4}/>{label}</button>)}</nav><div className="mt-10 hidden border-t hairline pt-5 text-xs leading-5 text-[#6f716e] lg:block">Your admin workspace is private to this browser session.</div></aside>
      <main className="min-w-0">
        <div className="flex flex-col justify-between gap-6 border-b hairline pb-8 md:flex-row md:items-end"><div><p className="eyebrow text-[#ac2536]">{pageIntro}</p><h1 className="mt-4 max-w-3xl font-serif text-6xl leading-[.85] md:text-8xl">{pageTitle}</h1></div>{tab === 'products' && <button onClick={addProduct} data-testid="button-add-product" className="flex items-center justify-center gap-2 bg-[#ac2536] px-5 py-4 font-mono text-[10px] uppercase tracking-[.15em] text-[#eee9dd]"><Plus size={16}/> Add a piece</button>}</div>
        {notice && <div data-testid="status-admin-notice" className="mt-8 flex items-center gap-2 border border-[#8c9e7c] bg-[#e4eadf] px-4 py-3 text-sm"><CircleCheck size={17}/> {notice}</div>}

        {tab === 'overview' && <div className="mt-10"><div className="grid gap-3 md:grid-cols-3"><div className="bg-[#1f293b] p-5 text-[#eee9dd]"><p className="eyebrow text-[#d66a60]">Live pieces</p><p className="mt-3 font-serif text-5xl">{products.length}</p><p className="mt-3 font-mono text-[9px] uppercase tracking-widest text-[#c8c1b3]">Across 6 categories</p></div><div className="bg-[#c9d0c6] p-5"><p className="eyebrow text-[#565d62]">Orders this week</p><p className="mt-3 font-serif text-5xl">18</p><p className="mt-3 font-mono text-[9px] uppercase tracking-widest text-[#565d62]">+4 from last week</p></div><div className="bg-[#d4beb0] p-5"><p className="eyebrow text-[#565d62]">Atelier revenue</p><p className="mt-3 font-serif text-5xl">$8,420</p><p className="mt-3 font-mono text-[9px] uppercase tracking-widest text-[#565d62]">September to date</p></div></div><div className="mt-14 grid gap-14 lg:grid-cols-[1.1fr_.9fr]"><section><div className="flex items-center justify-between border-b hairline pb-4"><h2 className="font-serif text-3xl">Recent orders</h2><button onClick={() => setTab('orders')} className="editorial-link font-mono text-[9px] uppercase tracking-widest">View tracking</button></div><div className="divide-y hairline">{seedOrders.map(o => <div key={o.id} className="py-4"><div className="flex justify-between"><p className="font-mono text-[10px] uppercase tracking-widest">{o.id}</p><span className="font-mono text-xs">{money(o.total)}</span></div><p className="mt-2 font-serif text-xl">{o.customer}</p><div className="mt-2 flex justify-between gap-3 text-xs text-[#6f716e]"><span>{o.item}</span><span className="font-mono text-[9px] uppercase tracking-widest">{o.status}</span></div></div>)}</div></section><section><div className="flex items-center justify-between border-b hairline pb-4"><h2 className="font-serif text-3xl">Payout snapshot</h2><button onClick={() => setTab('transactions')} className="editorial-link font-mono text-[9px] uppercase tracking-widest">All transactions</button></div><div className="mt-5 bg-[#eee9dd] p-6"><p className="eyebrow text-[#6f716e]">Available this week</p><p className="mt-3 font-serif text-5xl">$1,425</p><p className="mt-3 text-sm leading-6 text-[#6f716e]">{bank.bankName ? `Depositing to ${bank.bankName} ···· ${bank.accountNumberLast4}` : 'Add your payout details in Your details.'}</p><button onClick={() => setTab('settings')} className="editorial-link mt-6 font-mono text-[10px] uppercase tracking-widest">{bank.bankName ? 'Manage payout details' : 'Add payout details'}</button></div></section></div></div>}

        {tab === 'products' && <section className="mt-10"><div className="flex items-center justify-between border-b hairline pb-4"><h2 className="font-serif text-3xl">Collection</h2><span className="font-mono text-[9px] uppercase tracking-widest text-[#6f716e]">Edit in place</span></div><div className="mt-3 divide-y hairline">{products.map(p => <div key={p.id} className="flex items-center gap-4 py-4" data-testid={`row-admin-product-${p.id}`}><img src={p.image} alt="" className="h-16 w-14 object-cover object-[center_20%] mix-blend-multiply"/><div className="min-w-0 flex-1"><p className="font-serif text-xl">{p.name || 'Untitled piece'}</p><p className="mt-1 font-mono text-[9px] uppercase tracking-widest text-[#6f716e]">{p.category} · {p.stock} in stock</p></div><span className="hidden font-mono text-xs sm:block">{money(p.price)}</span><button onClick={() => setEditing(p)} aria-label={`Edit ${p.name}`} data-testid={`button-edit-${p.id}`} className="border hairline p-2 hover:border-[#ac2536] hover:text-[#ac2536]"><Pencil size={14}/></button><button onClick={() => remove(p.id)} aria-label={`Delete ${p.name}`} data-testid={`button-delete-${p.id}`} className="border hairline p-2 hover:border-[#ac2536] hover:text-[#ac2536]"><Trash2 size={14}/></button></div>)}</div></section>}

        {tab === 'orders' && <section className="mt-10"><div className="border-b hairline pb-4"><h2 className="font-serif text-3xl">Shipment tracking</h2><p className="mt-2 max-w-xl text-sm leading-6 text-[#6f716e]">Keep an eye on goods in transit and copy a tracking reference when you need to share an update.</p></div><div className="mt-3 divide-y hairline">{seedShipments.map(shipment => <div key={shipment.id} className="grid gap-4 py-5 md:grid-cols-[1fr_auto] md:items-center" data-testid={`row-shipment-${shipment.id.slice(1)}`}><div><div className="flex flex-wrap items-center gap-3"><span className="font-mono text-[10px] uppercase tracking-widest">{shipment.id}</span><span className="border border-[#8c9e7c] bg-[#e4eadf] px-2 py-1 font-mono text-[9px] uppercase tracking-widest text-[#4e6654]">{shipment.status}</span></div><p className="mt-2 font-serif text-2xl">{shipment.customer}</p><p className="mt-1 text-sm text-[#6f716e]">{shipment.item} · {shipment.carrier} · {shipment.eta}</p></div><div className="flex items-center gap-3 md:justify-end"><span className="font-mono text-[10px] uppercase tracking-widest text-[#6f716e]">{shipment.tracking}</span><button onClick={() => { navigator.clipboard?.writeText(shipment.tracking); flash('Tracking reference copied.'); }} data-testid={`button-copy-tracking-${shipment.id.slice(1)}`} className="border hairline p-2 hover:border-[#ac2536] hover:text-[#ac2536]" aria-label={`Copy tracking for ${shipment.id}`}><ClipboardList size={15}/></button></div></div>)}</div></section>}

        {tab === 'transactions' && <section className="mt-10"><div className="grid gap-3 md:grid-cols-3"><div className="bg-[#1f293b] p-5 text-[#eee9dd]"><p className="eyebrow text-[#d66a60]">Paid out</p><p className="mt-3 font-serif text-4xl">$1,705</p></div><div className="bg-[#c9d0c6] p-5"><p className="eyebrow text-[#565d62]">Processing</p><p className="mt-3 font-serif text-4xl">$260</p></div><div className="bg-[#d4beb0] p-5"><p className="eyebrow text-[#565d62]">Next payout</p><p className="mt-3 font-serif text-4xl">Fri 18</p></div></div><div className="mt-12 border-b hairline pb-4"><h2 className="font-serif text-3xl">Transaction history</h2></div><div className="divide-y hairline">{seedTransactions.map(transaction => <div key={transaction.id} className="grid gap-3 py-5 md:grid-cols-[1fr_1fr_auto_auto] md:items-center"><div><p className="font-mono text-[10px] uppercase tracking-widest">{transaction.id}</p><p className="mt-2 font-serif text-xl">{transaction.type}</p></div><div><p className="text-sm">{transaction.reference}</p><p className="mt-1 font-mono text-[9px] uppercase tracking-widest text-[#6f716e]">{transaction.date}</p></div><span className="font-mono text-sm">{money(transaction.amount)}</span><span className="font-mono text-[9px] uppercase tracking-widest text-[#4e6654]">{transaction.status}</span></div>)}</div></section>}

        {tab === 'settings' && <section className="mt-10 grid gap-10 xl:grid-cols-2"><form onSubmit={saveProfile} className="bg-[#eee9dd] p-6 md:p-8"><div className="flex items-start justify-between border-b hairline pb-5"><div><p className="eyebrow text-[#ac2536]">Account</p><h2 className="mt-2 font-serif text-3xl">Your details</h2></div><Mail size={18} strokeWidth={1.3}/></div><div className="mt-8 grid gap-5"><label><span className="eyebrow">Name</span><input value={profileForm.name} onChange={e => setProfileForm(f => ({ ...f, name: e.target.value }))} data-testid="input-admin-name" className="mt-2 w-full border-b hairline bg-transparent py-3 font-serif text-2xl outline-none"/></label><label><span className="eyebrow">Email address</span><div className="mt-2 flex items-center gap-3 border-b hairline"><Mail size={15} className="text-[#ac2536]"/><input type="email" value={profileForm.email} onChange={e => setProfileForm(f => ({ ...f, email: e.target.value }))} data-testid="input-admin-email" className="w-full bg-transparent py-3 text-sm outline-none"/></div></label><label><span className="eyebrow">Phone number</span><div className="mt-2 flex items-center gap-3 border-b hairline"><Phone size={15} className="text-[#ac2536]"/><input type="tel" value={profileForm.phone} onChange={e => setProfileForm(f => ({ ...f, phone: e.target.value }))} data-testid="input-admin-phone" className="w-full bg-transparent py-3 text-sm outline-none"/></div></label></div><button type="submit" data-testid="button-save-admin-profile" className="mt-8 flex items-center justify-center gap-2 bg-[#1f293b] px-5 py-4 font-mono text-[10px] uppercase tracking-[.15em] text-[#eee9dd]"><Save size={15}/> Save contact details</button></form><form onSubmit={saveBank} className="bg-[#eee9dd] p-6 md:p-8"><div className="flex items-start justify-between border-b hairline pb-5"><div><p className="eyebrow text-[#ac2536]">Payouts</p><h2 className="mt-2 font-serif text-3xl">Bank details</h2></div><CreditCard size={18} strokeWidth={1.3}/></div><p className="mt-5 text-sm leading-6 text-[#6f716e]">Use this for payout routing. For this demo, full account details are never saved; only the last four digits are kept for your reference.</p><div className="mt-8 grid gap-5"><label><span className="eyebrow">Account holder</span><input value={bankForm.accountName} onChange={e => setBankForm(f => ({ ...f, accountName: e.target.value }))} data-testid="input-bank-account-name" className="mt-2 w-full border-b hairline bg-transparent py-3 text-sm outline-none" placeholder="Your full name or business name"/></label><label><span className="eyebrow">Bank name</span><input value={bankForm.bankName} onChange={e => setBankForm(f => ({ ...f, bankName: e.target.value }))} data-testid="input-bank-name" className="mt-2 w-full border-b hairline bg-transparent py-3 text-sm outline-none" placeholder="Bank or financial institution"/></label><label><span className="eyebrow">Account number</span><input type="password" inputMode="numeric" value={bankForm.accountNumber} onChange={e => setBankForm(f => ({ ...f, accountNumber: e.target.value }))} data-testid="input-bank-account-number" className="mt-2 w-full border-b hairline bg-transparent py-3 text-sm outline-none" placeholder={bank.accountNumberLast4 ? `•••• ${bank.accountNumberLast4}` : 'Enter account number'}/></label><label><span className="eyebrow">Sort code / routing number</span><input type="password" inputMode="numeric" value={bankForm.sortCode} onChange={e => setBankForm(f => ({ ...f, sortCode: e.target.value }))} data-testid="input-bank-sort-code" className="mt-2 w-full border-b hairline bg-transparent py-3 text-sm outline-none" placeholder={bank.sortCodeLast4 ? `•••• ${bank.sortCodeLast4}` : 'Enter routing details'}/></label></div><button type="submit" data-testid="button-save-bank-details" className="mt-8 flex items-center justify-center gap-2 bg-[#ac2536] px-5 py-4 font-mono text-[10px] uppercase tracking-[.15em] text-[#eee9dd]"><Save size={15}/> Save payout details</button>{bank.updatedAt && <p className="mt-4 flex items-center gap-2 font-mono text-[9px] uppercase tracking-widest text-[#6f716e]"><MapPin size={13}/> Last updated {bank.updatedAt} · {bank.bankName} ···· {bank.accountNumberLast4}</p>}</form></section>}
      </main>
    </div>
    {editing && <ProductEditor product={editing} close={() => setEditing(null)} save={p => { setProducts(ps => { const exists = ps.some(x => x.id === p.id); return exists ? ps.map(x => x.id === p.id ? p : x) : [p, ...ps]; }); setEditing(null); flash('Collection saved.'); }}/>}
  </div>;
}

function ProductEditor({ product, close, save }: { product: Product; close: () => void; save: (p: Product) => void }) {
  const [form, setForm] = useState(product);
  const update = (key: keyof Product, value: string | number) => setForm(f => ({ ...f, [key]: value }));
  const uploadImage = (file?: File) => {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => { if (typeof reader.result === 'string') update('image', reader.result); };
    reader.readAsDataURL(file);
  };
  return <div className="fixed inset-0 z-40 overflow-auto bg-[#1f293b]/50 p-4 md:p-10"><div className="mx-auto max-w-2xl bg-[#eee9dd] p-6 md:p-10"><div className="flex items-start justify-between"><div><p className="eyebrow text-[#ac2536]">Catalog editor</p><h2 className="mt-3 font-serif text-5xl">{product.name ? 'Refine piece' : 'New piece'}</h2></div><button onClick={close} aria-label="Close editor" data-testid="button-close-editor"><X size={22}/></button></div><div className="mt-10 grid gap-5 md:grid-cols-2"><label className="md:col-span-2"><span className="eyebrow">Product image</span><div className="mt-2 flex items-center gap-4 border hairline p-3"><img src={form.image} alt="" className="h-24 w-20 object-cover object-[center_20%] mix-blend-multiply"/><div className="min-w-0"><label className="flex cursor-pointer items-center gap-2 bg-[#1f293b] px-4 py-3 font-mono text-[10px] uppercase tracking-widest text-[#eee9dd]"><Upload size={14}/> Upload image<input type="file" accept="image/*" onChange={e => uploadImage(e.target.files?.[0])} data-testid="input-product-image" className="sr-only"/></label><p className="mt-2 text-xs leading-5 text-[#6f716e]">Choose a product photo from your device. It is saved to this browser for the demo.</p></div></div></label><label className="md:col-span-2"><span className="eyebrow">Name</span><input value={form.name} onChange={e => update('name', e.target.value)} data-testid="input-product-name" className="mt-2 w-full border-b hairline bg-transparent py-3 font-serif text-2xl outline-none"/></label><label><span className="eyebrow">Category</span><select value={form.category} onChange={e => update('category', e.target.value)} data-testid="select-product-category" className="mt-2 w-full border-b hairline bg-transparent py-3 text-sm outline-none"><option>Outerwear</option><option>Trousers</option><option>Shirting</option><option>Knitwear</option><option>Separates</option></select></label><label><span className="eyebrow">Price</span><input type="number" value={form.price} onChange={e => update('price', Number(e.target.value))} data-testid="input-product-price" className="mt-2 w-full border-b hairline bg-transparent py-3 text-sm outline-none"/></label><label><span className="eyebrow">Stock</span><input type="number" value={form.stock} onChange={e => update('stock', Number(e.target.value))} data-testid="input-product-stock" className="mt-2 w-full border-b hairline bg-transparent py-3 text-sm outline-none"/></label><label><span className="eyebrow">Badge</span><input value={form.badge} onChange={e => update('badge', e.target.value)} data-testid="input-product-badge" className="mt-2 w-full border-b hairline bg-transparent py-3 text-sm outline-none"/></label><label className="md:col-span-2"><span className="eyebrow">Description</span><textarea value={form.description} onChange={e => update('description', e.target.value)} data-testid="input-product-description" rows={3} className="mt-2 w-full resize-none border-b hairline bg-transparent py-3 text-sm leading-6 outline-none"/></label></div><button onClick={() => save(form)} disabled={!form.name.trim()} data-testid="button-save-product" className="mt-10 flex w-full justify-center bg-[#ac2536] py-4 font-mono text-[10px] uppercase tracking-[.18em] text-[#eee9dd] disabled:opacity-40">Save piece <CircleCheck size={15} className="ml-2"/></button></div></div>;
}

function App() {
  const [products, setProducts] = useState<Product[]>(getProducts); const [cart, setCart] = useState<CartLine[]>(getCart); const [wished, setWished] = useState<string[]>(() => { try { return JSON.parse(localStorage.getItem('lume-wishlist') || '[]'); } catch { return []; } }); const [cartOpen, setCartOpen] = useState(false); const [searchOpen, setSearchOpen] = useState(false); const [toast, setToast] = useState('');
  useEffect(() => localStorage.setItem('lume-products', JSON.stringify(products)), [products]); useEffect(() => localStorage.setItem('lume-cart', JSON.stringify(cart)), [cart]); useEffect(() => localStorage.setItem('lume-wishlist', JSON.stringify(wished)), [wished]);
  const add = (product: Product, size: string) => { setCart(lines => { const found = lines.find(l => l.product.id === product.id && l.size === size); return found ? lines.map(l => l === found ? { ...l, quantity: l.quantity + 1 } : l) : [...lines, { product, size, quantity: 1 }]; }); setToast(`${product.name} added to your bag`); setCartOpen(true); setTimeout(() => setToast(''), 2600); };
  const update = (id: string, size: string, delta: number) => setCart(lines => lines.map(l => l.product.id === id && l.size === size ? { ...l, quantity: l.quantity + delta } : l).filter(l => l.quantity > 0));
  const toggleWish = (id: string) => setWished(w => w.includes(id) ? w.filter(x => x !== id) : [...w, id]);
  const cartCount = cart.reduce((s, l) => s + l.quantity, 0);
  return <div className="grain min-h-[100dvh]"><Switch><Route path="/admin/login"><AdminLogin onLogin={() => {}}/></Route><Route path="/admin"><Admin products={products} setProducts={setProducts}/></Route><Route path="/shop"><Shop products={products} onWishlist={toggleWish} wished={wished} cartCount={cartCount} onCart={() => setCartOpen(true)} onSearch={() => setSearchOpen(true)}/></Route><Route path="/product/:id"><ProductDetail products={products} add={add} onWishlist={toggleWish} wished={wished} cartCount={cartCount} onCart={() => setCartOpen(true)} onSearch={() => setSearchOpen(true)}/></Route><Route path="/"><><Header cartCount={cartCount} onCart={() => setCartOpen(true)} onSearch={() => setSearchOpen(true)}/><Home products={products} onWishlist={toggleWish} wished={wished} onSearch={() => setSearchOpen(true)}/></></Route></Switch>{cartOpen && <CartDrawer cart={cart} close={() => setCartOpen(false)} update={update} checkout={() => { setToast('Checkout is ready for your details.'); setCartOpen(false); setTimeout(() => setToast(''), 2800); }}/>} {searchOpen && <SearchOverlay products={products} close={() => setSearchOpen(false)} onWishlist={toggleWish} wished={wished}/>} {toast && <div data-testid="status-toast" className="fixed bottom-5 left-1/2 z-[60] -translate-x-1/2 bg-[#1f293b] px-5 py-3 font-mono text-[10px] uppercase tracking-widest text-[#eee9dd] shadow-xl">{toast}</div>}</div>;
}

const queryClient = new QueryClient();
export default function Root() { return <QueryClientProvider client={queryClient}><App/></QueryClientProvider>; }